demo.program:
// Signature Flight Core layer check (simulated model)
var layers=['mission-apps','SigCore','SigOS','SigPlat','hardware'];
console.log('SFC stack: '+layers.join(' > '));
console.log('original Signature design, '+layers.length+' layers');

// SigCore app registry demo (simulated model)
var apps=[['SIG-HK',201],['SIG-SCH',202],['SIG-TBL',203]];
for(var i=0;i<apps.length;i++){console.log('registered '+apps[i][0]+' id='+apps[i][1]);}
console.log(apps.length+' Signature apps under SigCore Executive');

// SigBus routing demo (simulated model)
var routes={'0x2001':['SIG-HK'],'0x2002':['SIG-SCH','SIG-TBL']};
var sent=0;
for(var mid in routes){sent+=routes[mid].length;console.log(mid+' -> '+routes[mid].join(','));}
console.log('SigBus delivered '+sent+' subscriptions');

// SigEvents severity filter demo (simulated model)
var evts=[['SIG-HK',1],['SIG-SCH',3],['SIG-TBL',4]], thr=2, n=0;
for(var i=0;i<evts.length;i++){if(evts[i][1]>=thr){n++;console.log(evts[i][0]+' sev '+evts[i][1]);}}
console.log(n+' events passed severity '+thr);

// SigTables activation demo (simulated model)
function chk(o){var s=JSON.stringify(o),h=7;for(var i=0;i<s.length;i++){h=(h*33+s.charCodeAt(i))>>>0;}return h;}
var edit={thr:42}, active={thr:40};
console.log('edit chk='+chk(edit)+' active chk='+chk(active));
active=edit;console.log('activated thr='+active.thr);

// SigTime conversion demo (simulated model)
var smet=34560000, leap=37;
var utc=smet-leap;
console.log('SMET '+smet+' -> UTC offset applied ('+leap+'s leap)');
console.log('correlated UTC seconds: '+utc);

// SigOS task demo (simulated model)
var n=0;
function Sig_TaskSpawn(nm){n++;return nm+'#'+n;}
console.log(Sig_TaskSpawn('SIG-HK')+' '+Sig_TaskSpawn('SIG-SCH'));
console.log('one SigOS API, many OSes underneath');

// SigPlat bring-up demo (simulated model)
var plat={tick:100,wd:true,ok:0};
var checks=['boot','tick','uart','nvm','watchdog'];
for(var i=0;i<checks.length;i++){plat.ok++;console.log(checks[i]+' ... ok');}
console.log('SigPlat bring-up '+plat.ok+'/'+checks.length);

// SIG-SCH dispatch demo (simulated model)
var plan=[['SIG-HK','0x2001'],['SIG-TBL','0x2003']];
for(var f=0;f<2;f++){for(var i=0;i<plan.length;i++){console.log('frame '+f+': '+plan[i][1]+' -> '+plan[i][0]);}}
console.log('SIG-SCH dispatched '+(plan.length*2)+' messages');

// SigPacket header demo (simulated model)
var mid=0x2001, seq=7, len=48;
var h=(mid<<16)|(seq<<8)|len;
console.log('SigPacket mid=0x'+mid.toString(16)+' seq='+seq);
console.log('packed=0x'+h.toString(16)+' mid back=0x'+((h>>16)&0xffff).toString(16));

// SFC build matrix demo (simulated model)
var t=[['desktop','dev'],['sig-board-a','flight'],['sig-board-b','flight']];
for(var i=0;i<t.length;i++){console.log('build '+t[i][0]+' ('+t[i][1]+') OK');}
console.log(t.length+' targets, one Signature tree');

// SFC mission reuse demo (simulated model)
var m=[['SIG-Orbiter',8],['SIG-Lander',11],['SIG-SmallSat',6]], tot=0;
for(var i=0;i<m.length;i++){tot+=m[i][1];console.log(m[i][0]+': '+m[i][1]+' mission apps');}
console.log(tot+' mission apps, one SigCore');

// SFC coverage gate demo (simulated model)
var mods=[['SigCore',92],['SigBus',90],['SigOS',87]], gate=85, p=0;
for(var i=0;i<mods.length;i++){var ok=mods[i][1]>=gate;if(ok)p++;console.log(mods[i][0]+' '+mods[i][1]+'% '+(ok?'PASS':'FAIL'));}
console.log(p+'/'+mods.length+' above gate');

// SFC portability demo (simulated model)
var cfgs=['desktop','flight-a','flight-b'];
for(var i=0;i<cfgs.length;i++){console.log('SigOS/'+cfgs[i]+': same app source OK');}
console.log('portable across '+cfgs.length+' SigOS targets');

// Signature end-to-end demo (simulated model)
var steps=['uplink','SigBus route','app acts','SIG-HK','SigEvents','downlink'], t=0;
for(var i=0;i<steps.length;i++){t+=10;console.log('t+'+t+'ms '+steps[i]);}
console.log('Signature loop closed in '+t+'ms');
